import{_ as l,C as e,o as s,c as i,a6 as a,E as r}from"./chunks/framework.BlDtR6jM.js";const h=JSON.parse('{"title":"神遗：蒸汽妖都 - 流程模拟器","description":"","frontmatter":{"layout":"page","pageClass":"workshop-tool","title":"神遗：蒸汽妖都 - 流程模拟器","comments":false,"readingTime":"3 min read"},"headers":[],"relativePath":"创意工坊/游戏数值模拟器.md","filePath":"创意工坊/游戏数值模拟器.md"}'),n={name:"创意工坊/游戏数值模拟器.md"};function _(d,t,p,c,m,g){const o=e("JRPGSimulator");return s(),i("div",null,[t[0]||(t[0]=a('<h1 id="神遗-蒸汽妖都-流程模拟器" tabindex="-1">神遗：蒸汽妖都 - 流程模拟器 <a class="header-anchor" href="#神遗-蒸汽妖都-流程模拟器" aria-label="Permalink to &quot;神遗：蒸汽妖都 - 流程模拟器&quot;">​</a></h1><p>本工具专为项目《神遗：蒸汽妖都》设计，用于验证游戏主线流程的节奏、卡点难度以及总时长预估。</p><div class="info custom-block"><p class="custom-block-title">核心功能</p><ul><li><strong>主线验证</strong>：模拟从《外滩码头》到《昆仑神墟》的完整章节流程。</li><li><strong>队伍模拟</strong>：计算陈少秋、林晚晴、朱利安等角色加入后的队伍综合战力。</li><li><strong>卡点分析</strong>：识别关键BOSS战（如“铁手原型机”）的难度评级（Normal/Hard/Impossible）。</li><li><strong>时长预估</strong>：基于怪物经验与升级曲线，计算练级（Grind）所需的枯燥时间。</li></ul></div>',3)),r(o),t[1]||(t[1]=a('<h2 id="模拟机制说明" tabindex="-1">模拟机制说明 <a class="header-anchor" href="#模拟机制说明" aria-label="Permalink to &quot;模拟机制说明&quot;">​</a></h2><h3 id="_1-队伍系统-party-system" tabindex="-1">1. 队伍系统 (Party System) <a class="header-anchor" href="#_1-队伍系统-party-system" aria-label="Permalink to &quot;1. 队伍系统 (Party System)&quot;">​</a></h3><p>模拟器不再计算单一主角，而是计算当前剧情节点的<strong>队伍总战力</strong>。</p><ul><li><strong>陈少秋</strong>：高攻成长，武器强化核心。</li><li><strong>林晚晴</strong>（第二章加入）：提供治疗与辅助，增加容错。</li><li><strong>朱利安</strong>（第三章加入）：控制与工程技能。</li></ul><h3 id="_2-关键事件-milestone-events" tabindex="-1">2. 关键事件 (Milestone Events) <a class="header-anchor" href="#_2-关键事件-milestone-events" aria-label="Permalink to &quot;2. 关键事件 (Milestone Events)&quot;">​</a></h3><p>流程中包含影响数值的关键事件：</p><ul><li><strong>Craft Nuwa Weapon</strong>：在陈氏公馆制造娲石武器，大幅提升攻击力。若未完成此事件，后续BOSS难度将提升为 <strong>Hard/Impossible</strong>。</li><li><strong>Scripted Loss</strong>：剧情必败战斗（如拍卖行战宋先生），模拟器会自动标记为预期失败。</li></ul><h3 id="_3-难度评级-difficulty-rating" tabindex="-1">3. 难度评级 (Difficulty Rating) <a class="header-anchor" href="#_3-难度评级-difficulty-rating" aria-label="Permalink to &quot;3. 难度评级 (Difficulty Rating)&quot;">​</a></h3><p>基于BOSS战模拟结果自动评级：</p><ul><li><span style="color:#00695c;font-weight:bold;">Normal</span>：回合数适中 (3-20回合)，血量健康。</li><li><span style="color:#e65100;font-weight:bold;">Hard</span>：险胜 (剩余HP &lt; 30%)。</li><li><span style="color:#c62828;font-weight:bold;">Extreme</span>：濒死 (剩余HP &lt; 10%)。</li><li><span style="color:#37474f;font-weight:bold;">Impossible</span>：队伍全灭。</li><li><span style="color:#33691e;font-weight:bold;">Trivial</span>：秒杀 (回合数 &lt; 3)，说明数值碾压。</li></ul>',10))])}const f=l(n,[["render",_]]);export{h as __pageData,f as default};
